create table DEVICE_INFO
(
    ID                 CHARACTER VARYING(50) not null,
    PARENT_ID          CHARACTER VARYING(50),
    NAME               CHARACTER VARYING(255),
    VOLTAGE            CHARACTER VARYING(50),
    TYPE               CHARACTER VARYING(255),
    PATTERN_ID         CHARACTER VARYING(255),
    SIGNAL_TEMPLATE_ID CHARACTER VARYING(50),
    BAY_NAME           CHARACTER VARYING(100)
);

comment on table DEVICE_INFO is '设备信息表';
comment on column DEVICE_INFO.ID is '设备Id';
comment on column DEVICE_INFO.PARENT_ID is '父设备id';
comment on column DEVICE_INFO.NAME is '设备名称';
comment on column DEVICE_INFO.VOLTAGE is '电压';
comment on column DEVICE_INFO.TYPE is '设备类型';
comment on column DEVICE_INFO.SIGNAL_TEMPLATE_ID is '信号模板id';
comment on column DEVICE_INFO.BAY_NAME is '间隔';


create table DEVICE_INFO_SIGNAL(
       ID CHARACTER VARYING(50) NOT NULL,
       DEVICE_INFO_ID CHARACTER VARYING(50) NOT NULL,
       DEVICE_NAME_IN_SIGNAL CHARACTER VARYING(50),
       SIGNAL_TYPE CHARACTER VARYING(255),
       SIGNAL_TEMPLATE CHARACTER VARYING(50),
       SIGNAL CHARACTER VARYING(255),
       BAY_NAME CHARACTER VARYING(100),
       NORMAL_STATUS CHARACTER VARYING(20),
       REMOTE_SIGNALING_TYPE CHARACTER VARYING(50)
);
comment on table DEVICE_INFO_SIGNAL IS '设备信号表';
comment on column DEVICE_INFO_SIGNAL.ID IS '主键';
comment on column DEVICE_INFO_SIGNAL.DEVICE_INFO_ID IS 'DEVICE_INFO ID';
comment on column DEVICE_INFO_SIGNAL.DEVICE_NAME_IN_SIGNAL IS '信号模板中替换使用';
comment on column DEVICE_INFO_SIGNAL.SIGNAL_TYPE IS '信号类型';
comment on column DEVICE_INFO_SIGNAL.SIGNAL_TEMPLATE IS '信号模板';
comment on column DEVICE_INFO_SIGNAL.SIGNAL IS '信号';
comment on column DEVICE_INFO_SIGNAL.BAY_NAME IS '间隔';
comment on column DEVICE_INFO_SIGNAL.NORMAL_STATUS IS '信号常态';
comment on column DEVICE_INFO_SIGNAL.REMOTE_SIGNALING_TYPE IS '遥信类型';


create table SIGNAL_TEMPLATE
(
    ID   CHARACTER VARYING(50) not null,
    NAME CHARACTER VARYING(50)
);
comment on table SIGNAL_TEMPLATE is '设备信号模板表';
comment on column SIGNAL_TEMPLATE.ID is '主键';
comment on column SIGNAL_TEMPLATE.NAME is '设备信号模板名称';


create table SIGNAL_TEMPLATE_DETAIL
(
    ID                    CHARACTER VARYING(50)  not null,
    TEMPLATE_ID           CHARACTER VARYING(50)  not null,
    DESC                  CHARACTER VARYING(50)  not null,
    TYPE                  CHARACTER VARYING(50)  not null,
    CONTENT               CHARACTER VARYING(255) not null,
    SAMPLE                CHARACTER VARYING(50),
    BAY_NAME              CHARACTER VARYING(255),
    NORMAL_STATUS         CHARACTER VARYING(255),
    REMOTE_SIGNALING_TYPE CHARACTER VARYING(255)
);

comment on table SIGNAL_TEMPLATE_DETAIL is '设备信号模板表';
comment on column SIGNAL_TEMPLATE_DETAIL.ID is '主键';
comment on column SIGNAL_TEMPLATE_DETAIL.TEMPLATE_ID is '设备信号模板ID';
comment on column SIGNAL_TEMPLATE_DETAIL.DESC is '信号名称';
comment on column SIGNAL_TEMPLATE_DETAIL.TYPE is '信号类型';
comment on column SIGNAL_TEMPLATE_DETAIL.CONTENT is '信号内容';
comment on column SIGNAL_TEMPLATE_DETAIL.SAMPLE is '信号描述';
comment on column SIGNAL_TEMPLATE_DETAIL.BAY_NAME is '间隔';
comment on column SIGNAL_TEMPLATE_DETAIL.NORMAL_STATUS is '信号常态';
comment on column SIGNAL_TEMPLATE_DETAIL.REMOTE_SIGNALING_TYPE is '遥信类型';

